@props(['nodes'])
<div id="node-drawer" class="drawer-backdrop"><aside class="drawer" role="dialog" aria-modal="true"><button class="drawer-close" type="button">×</button><div id="detail-content"></div></aside></div>
<script type="application/json" id="network-node-data">{!! json_encode(array_values($nodes), JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) !!}</script>
<script>(()=>{const r=document.getElementById('node-drawer'),o=document.getElementById('detail-content'),ns=JSON.parse(document.getElementById('network-node-data').textContent),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),l=a=>a?.length?'<ul>'+a.map(x=>'<li>'+e(x)+'</li>').join('')+'</ul>':'<p class="muted">Sin capacidades registradas.</p>';document.addEventListener('click',x=>{const t=x.target.closest('[data-node]');if(t){const n=ns.find(v=>v.code===t.dataset.node),a=n.resolved_url?'<a class="btn" href="'+e(n.resolved_url)+'">ABRIR MÓDULO</a>':'<span class="btn disabled">'+(n.implementation_status==='external'?'PLATAFORMA EXTERNA':n.implementation_status==='planned'?'PLANEADO':'MÓDULO TODAVÍA NO DISPONIBLE')+'</span>';o.innerHTML='<div class="eyebrow">'+e(n.group)+' · '+e(n.code)+'</div><h2>'+e(n.label)+'</h2><span class="badge status-'+e(n.implementation_status)+'">'+e(n.implementation_status.toUpperCase())+'</span><p>'+e(n.description)+'</p><h4>Capacidades actuales</h4>'+l(n.current_capabilities)+'<h4>Capacidades futuras</h4>'+l(n.future_capabilities)+'<h4>Dependencias</h4>'+l(n.dependencies)+'<h4>Conexiones</h4>'+l(n.connections.map(v=>v.from+' → '+v.to+' ['+v.status.toUpperCase()+']'))+(n.commercial_module_code?'<p><b>Módulo comercial:</b> '+e(n.commercial_module_code)+'</p>':'')+(n.notes?'<p><b>Notas:</b> '+e(n.notes)+'</p>':'')+a;r.classList.add('open')}if(x.target===r||x.target.closest('.drawer-close'))r.classList.remove('open')});document.addEventListener('keydown',x=>{if(x.key==='Escape')r.classList.remove('open')})})();</script>
